(function(root){
'use strict';
const modes={
immanuel:['Immanuel manual','State prerequisites, steps, completion checks, and stop conditions.'],
emanuel:['Emanuel manual','Record a repeatable procedure and its review responsibilities.'],
advocacy:['Advocacy','Distinguish evidence, claims, opinions, affected interests, and the requested remedy. No outreach or campaigning occurs automatically.'],
strategy:['Strategy / stragego','Record alternatives, assumptions, resources, decision criteria, and a review point.'],
'ostar-makkakah':['Ostar rawful lair makkakah','Sustain a useful voluntary practice through care, observation, and review.'],
'ostar-aantonymmakkakah':['Ostar rawful lair aantonymmakkakah','Reconsider framing and open a route to repair while preserving useful work.'],
jurisdiction:['Jurisdiction review','UNREVIEWED: identify applicable law, current authoritative sources, rights, permissions, and appropriate review. No legal validity is certified.']
};
function bounded(value,max=100000){if(typeof value!=='string'||value.length>max)throw Error('Text exceeds its field limit');return value;}
function manual(mode,fields){if(!Object.hasOwn(modes,mode))throw Error('Unknown manual mode');const sections=[['title','Title'],['purpose','Purpose and audience'],['procedure','Procedure / evidence / alternatives'],['acceptance','Acceptance and stop conditions'],['rights','Rights and boundaries'],['locations','Declared locations'],['review','Unresolved review questions']];return ['# '+modes[mode][0],'','Status: UNREVIEWED DRAFT','',...sections.flatMap(([key,label])=>['## '+label,bounded(fields[key],5000).trim()||'Not specified','']),'## Mode guidance',modes[mode][1],'','This is a generated planning document, not approval, verified advice, or an implemented specialist service.'].join('\n');}
function rewrite(source,find,replacement){bounded(source);bounded(find,1000);bounded(replacement,5000);if(!find)throw Error('Find text cannot be empty');const parts=source.split(find),count=parts.length-1,size=source.length+count*(replacement.length-find.length);if(size>100000)throw Error('Rewritten text exceeds the output limit');return {text:parts.join(replacement),count};}
function program(message){bounded(message);const bytes=new TextEncoder().encode(message);if(bytes.length>4095)throw Error('Message exceeds 4095 UTF-8 bytes');const lines=['; Generated K0 UTF-8 console program'];for(const byte of bytes)lines.push('mark r0 '+byte,'signal r0 0 1');lines.push('signal r0 2 1');return lines.join('\n')+'\n';}
function blueprint(source){bounded(source,10000);const components=[];for(const [index,line] of source.split(/\r?\n/).entries()){if(!line.trim())continue;const cells=line.split('|').map(s=>s.trim());if(cells.length<2||cells.length>3)throw Error('Line '+(index+1)+': use id | title | dependencies');const [id,title,raw='']=cells;if(!/^[A-Za-z0-9_-]{1,80}$/.test(id)||!title||title.length>300)throw Error('Invalid component ID or title');if(components.some(c=>c.id===id))throw Error('Duplicate component ID: '+id);const dependencies=raw.split(',').map(s=>s.trim()).filter(Boolean);if(new Set(dependencies).size!==dependencies.length)throw Error('Duplicate dependency');components.push({id,title,dependencies});if(components.length>100)throw Error('Component limit is 100');}if(!components.length)throw Error('Enter at least one component');const map=new Map(components.map(c=>[c.id,c])),visiting=new Set(),done=new Set(),order=[];function visit(id){if(done.has(id))return;if(visiting.has(id))throw Error('Dependency cycle at '+id);if(!map.has(id))throw Error('Undefined dependency: '+id);visiting.add(id);for(const dep of map.get(id).dependencies)visit(dep);visiting.delete(id);done.add(id);order.push(id);}for(const c of components)visit(c.id);return {format:'rasniki-blueprint',version:1,status:'unreviewed planning record',components,constructionOrder:order};}
root.RasnikiManuals={modes,manual,rewrite,program,blueprint};
})(globalThis);
